INSERT INTO rpg_weapon_types (id, job_id, name, visual, elemental_capable, description, traits, sort_order)
VALUES
  ('lk_sword', 'light_knight', '單手劍', 'sword', TRUE, '攻守均衡的單手劍，部分稀有版本可額外提升魔法攻擊力。', '{"positioning":"物理攻擊力","style":"均衡輸出","elemental_capable":true,"special":"屬性版額外提供魔法攻擊力加成（matk 由 4 隨等級成長至 40）"}'::jsonb, 1),
  ('lk_dual', 'light_knight', '雙劍', 'sword', FALSE, '雙劍在手化身二刀流，攻擊拆為兩段但每段威力僅有六成。', '{"positioning":"物理攻擊力","style":"二刀流","hits":2,"hit_mul":0.6,"special":"總傷害期望值約為單段攻擊的 120%，但雙段各自獨立判定 miss／暴擊，變異度較高"}'::jsonb, 2),
  ('lk_rapier', 'light_knight', '細劍', 'sword', FALSE, '劍身輕薄利於快速出招，稀有度越高攻擊間隔縮短越多，對小型目標更有效。', '{"positioning":"物理攻擊力","style":"攻速型","interval_pct_by_rarity":{"common":-6,"rare":-10,"epic":-14,"legendary":-20},"size_bonus":{"small":5},"special":"稀有度越高攻擊間隔縮短越多，對小型怪物 +5% 傷害"}'::jsonb, 3),
  ('ar_longbow', 'archer', '長弓', 'bow', FALSE, '蓄力拉滿弓弦、攻擊間隔拉長但箭勁十足，並顯著提升爆擊傷害，克制大型目標。', '{"positioning":"物理攻擊力","style":"重擊型","interval_pct":20,"crit_dmg_pct_range":[5,15],"size_bonus":{"large":5},"special":"攻擊間隔拉長換取高爆擊傷害，對大型怪物 +5% 傷害"}'::jsonb, 4),
  ('ar_shortbow', 'archer', '短弓', 'bow', TRUE, '輕巧好操作、出手極快，並附加迴避率加成。', '{"positioning":"物理攻擊力","style":"速射型","interval_pct":-10,"flee_bonus_range":[3,12],"elemental_capable":true,"special":"出手極快、附加迴避率加成"}'::jsonb, 5),
  ('ar_crossbow', 'archer', '弩', 'bow', FALSE, '扣下扳機瞬間擊發、攻擊間隔全弓種最短，弩箭爆擊格外致命。', '{"positioning":"物理攻擊力","style":"極速型","interval_pct":-25,"crit_dmg_pct_range":[8,20],"special":"全弓種最短攻擊間隔，換取更高爆擊傷害"}'::jsonb, 6),
  ('mg_staff', 'mage', '杖', 'staff', FALSE, '魔法師專用權杖，內建節拍器般的訊號迴路，額外增幅智力與魔力上限，是續航型法系武器的基本款。', '{"role":"續航系法杖，主攻資源與屬性成長","primary_stat":"matk","matk_coefficient":1.0,"growth":{"int_bonus":[2,12],"mp_pct_low_high":[5,20]},"flavor_note":"杖身鑲嵌訊號石，越高階越能穩定放大智力與魔力儲備。"}'::jsonb, 1),
  ('mg_rod', 'mage', '棍', 'staff', FALSE, '魔法師專用短棍，導入城市電網過載的能量迴路，直接放大魔法攻擊力輸出。', '{"role":"輸出系法棍，主攻魔法攻擊力百分比成長","primary_stat":"matk","matk_coefficient":1.0,"growth":{"matk_pct_low_high":[5,20]},"flavor_note":"棍身導電材質隨等級提升，魔攻加成越發顯著。"}'::jsonb, 2),
  ('mg_book', 'mage', '書', 'staff', FALSE, '記錄城市熱島效應觀測資料的法術手冊，魔攻略遜於杖棍，但能穩定強化魔法技能效果。', '{"role":"技能強化型法書，犧牲部分魔攻換取技能效果加成","primary_stat":"matk","matk_coefficient":0.85,"growth":{"magic_skill_pct_fixed":5},"flavor_note":"書頁夾滿觀測筆記，翻閱間讓每個法術系數再往上推一點。"}'::jsonb, 3),
  ('cl_staff', 'cleric', '杖', 'staff', FALSE, '聖職者專用權杖，如隨身急救箱般延伸，額外增加智力與魔力上限，供長時間支援隊友使用。', '{"role":"續航系聖杖，主攻資源與屬性成長","primary_stat":"matk","matk_coefficient":1.0,"growth":{"int_bonus":[2,12],"mp_pct_low_high":[5,20]},"flavor_note":"杖頭纏繞如繃帶的織帶，越高階越能撐住更長的治療節奏。"}'::jsonb, 1),
  ('cl_book', 'cleric', '書', 'staff', FALSE, '記載補給站陣線佈署要領的隨身手冊，魔攻略遜於杖鍊，但能穩定強化魔法技能效果。', '{"role":"技能強化型聖書，犧牲部分魔攻換取技能效果加成","primary_stat":"matk","matk_coefficient":0.85,"growth":{"magic_skill_pct_fixed":5},"flavor_note":"書頁邊角寫滿補給站佈點筆記，翻開就能讓治療與增益更扎實一分。"}'::jsonb, 2),
  ('cl_chain', 'cleric', '鍊', 'staff', FALSE, '由運動貼紮術延伸出的護具鍊，強化魔法抗性並提升魔法防禦，是防護型聖職者的首選。', '{"role":"防護系聖鍊，主攻屬性減免與魔防成長","primary_stat":"matk","matk_coefficient":1.0,"growth":{"element_resist_pct_low_high":[5,25],"mdef_pct_low_high":[5,15]},"flavor_note":"鍊環間穿著護具貼布，能把屬性傷害的衝擊層層卸掉。"}'::jsonb, 3),
  ('mc_hammer', 'merchant', '錘', 'sword', FALSE, '商人秤重用的實心秤錘，掄起來格外沉手，大幅提升爆擊傷害，對大體型的對手特別有效。', '{"role":"爆擊系商用錘，主攻爆擊傷害成長","primary_stat":"atk","atk_coefficient":1.0,"growth":{"crit_dmg_pct_low_high":[5,20]},"size_bonus":{"large":5},"flavor_note":"秤錘越重，砸中要害時的傷害翻倍效果也越明顯。"}'::jsonb, 1),
  ('mc_mallet', 'merchant', '槌', 'sword', FALSE, '夜市叫賣時敲擊招牌用的木槌，敲得越響、力道越足，物理攻擊力額外提升，對大體型的對手特別有效。', '{"role":"輸出系商用槌，主攻物理攻擊力百分比成長","primary_stat":"atk","atk_coefficient":1.0,"growth":{"atk_pct_low_high":[5,15]},"size_bonus":{"large":5},"flavor_note":"槌頭包覆的皮革隨等級升級，捶擊力道跟著水漲船高。"}'::jsonb, 2),
  ('mc_club', 'merchant', '棒', 'sword', FALSE, '顧攤蹲點時用來撐場面的木棒，扎實好握，額外提升物理防禦力，對大體型的對手特別有效。', '{"role":"防護系商用棒，主攻物理防禦力百分比成長","primary_stat":"atk","atk_coefficient":1.0,"growth":{"def_pct_low_high":[5,15]},"size_bonus":{"large":5},"flavor_note":"棒身刻滿顧攤多年的防身心得，扛得住的攻勢也越來越多。"}'::jsonb, 3),
  ('hk_greatsword', 'heavy_knight', '巨劍', 'greatsword', FALSE, '揮動前需蓄力，一旦劈下傷害倍增，尤其克制大型目標。', '{"positioning":"物理攻擊力","style":"蓄力型","charge_time_mul":1.5,"charge_dmg_mul_range":[1.6,2.0],"size_bonus":{"large":5},"special":"蓄力時間拉長為 1.5 倍，蓄力後傷害大幅提升，對大型怪物 +5% 傷害"}'::jsonb, 7),
  ('hk_spear', 'heavy_knight', '槍', 'greatsword', TRUE, '槍尖連刺兩段、威力各半，卻大幅提升爆擊率與爆擊傷害，偶有第三段追擊。', '{"positioning":"物理攻擊力","style":"連擊型","hits":2,"hit_mul":0.5,"crit_pct_range":[3,10],"crit_dmg_pct_range":[5,15],"extra_hit_chance_pct_range":[10,30],"elemental_capable":true,"special":"普攻固定兩段各 50% 傷害，並有機率追加第三段（10%→30%）"}'::jsonb, 8),
  ('hk_axe', 'heavy_knight', '斧', 'greatsword', FALSE, '掄動間隔較長，卻能橫掃左右鄰近目標，對大型目標傷害更高。', '{"positioning":"物理攻擊力","style":"範圍型","interval_pct":25,"splash_pct":40,"size_bonus":{"large":5},"special":"攻擊間隔變長，對主目標左右相鄰怪物造成 40% 濺射傷害，對大型怪物 +5% 傷害"}'::jsonb, 9)
