  ('lk_sword_t4_wood', 'lk_sword', 4, '夜騎巡邏劍‧森', 'rare', 30, 'wood', '{"atk":32,"element":"wood","matk":16}'::jsonb, '夜跑俱樂部指定強化款，攻守均衡的單手劍，部分稀有版本可額外提升魔法攻擊力，並融合木屬性之力，可對相剋的敵人造成加成傷害。', TRUE, 402),
