-- 183_rpg_weapons_elements.sql
-- DORPG P7：武器系統＋怪物體型／屬性實裝（契約見
-- scratchpad/dorpg_p7/{CONTRACT.md,WIRE.md}）。本檔只建表／加索引；18 種武器類型＋390 件武器的
-- seed 由另一個 Workflow 產生，貼進下方兩對標記之間（刻意放在兩張表都建好之後，seed 才有表可插）。
--
-- ⚠️ 使用者手動套用到 Neon，不得自行套用；全部 CREATE TABLE IF NOT EXISTS，seed 一律
-- ON CONFLICT (id) DO NOTHING，可安全重複執行。依規範（db-before-code-push.md）等使用者確認已
-- 套用才能 push 依賴這些新表的程式碼——content_repo.go 對「表不存在」(42P01) 有 isMissingRelation
-- 優雅降級成 503，但這是全新表，不像 180 那批「既有表加欄位」有 42703 風險。
--
-- 怪物體型（大/中/小）與屬性（金/木/水/火/土/光/闇）欄位本輪不需要新增：rpg_monsters.attribute/
-- size 從 migration 176 就已存在（見 internal/rpg/content.go 檔頭「攻擊屬性 A 對怪物屬性 M」相關
-- 註解），過去只當純顯示文字；本檔起 internal/rpg/elements.go 的 ElementMultiplier() 真的讀它們
-- 進戰鬥公式，資料庫結構完全不用動。

-- ---------------------------------------------------------------------------
-- 1) rpg_weapon_types：18 種武器類型（六職業 × 三種，CONTRACT §2）。
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS rpg_weapon_types (
  id                TEXT PRIMARY KEY,   -- lk_sword/lk_dual/lk_rapier/ar_longbow/ar_shortbow/ar_crossbow/
                                         -- mg_staff/mg_rod/mg_book/cl_staff/cl_book/cl_chain/
                                         -- mc_hammer/mc_mallet/mc_club/hk_greatsword/hk_spear/hk_axe
  job_id            TEXT NOT NULL REFERENCES rpg_jobs(id),
  name              TEXT NOT NULL,                     -- 單手劍/雙劍/細劍/長弓/…
  visual            TEXT NOT NULL DEFAULT 'sword',      -- sword|staff|bow|greatsword（既有四套 FX）
  elemental_capable BOOLEAN NOT NULL DEFAULT FALSE,     -- 這個類型是否另設一組七屬性版本（lk_sword/ar_shortbow/hk_spear=true）
  description       TEXT NOT NULL DEFAULT '',
  traits            JSONB NOT NULL DEFAULT '{}',        -- 型別層固定特性，純供顯示/設計依據，引擎不直接消費
  sort_order        INT NOT NULL DEFAULT 0,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ---------------------------------------------------------------------------
-- 2) rpg_weapons：每個類型 10 級（有屬性版的類型另 10 級 × 7 屬性）。
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS rpg_weapons (
  id            TEXT PRIMARY KEY,               -- <type>_t<tier> 或 <type>_t<tier>_<element>
  type_id       TEXT NOT NULL REFERENCES rpg_weapon_types(id),
  tier          INT NOT NULL CHECK (tier BETWEEN 1 AND 10),
  name          TEXT NOT NULL,
  rarity        TEXT NOT NULL DEFAULT 'common', -- common(t1-3)|rare(t4-6)|epic(t7-9)|legendary(t10)
  level_req     INT NOT NULL DEFAULT 1,         -- tier→1/10/20/30/40/50/60/70/80/90
  element       TEXT NOT NULL DEFAULT 'neutral', -- neutral 或七屬性英文代碼（metal/wood/water/fire/earth/light/dark）
  profile       JSONB NOT NULL DEFAULT '{}',    -- WeaponProfile，見 internal/rpg/weapons.go；缺欄位＝中性值
  description   TEXT NOT NULL DEFAULT '',
  is_active     BOOLEAN NOT NULL DEFAULT TRUE,
  sort_order    INT NOT NULL DEFAULT 0,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_rpg_weapons_type_tier ON rpg_weapons(type_id, tier);

-- >>> WEAPONS SEED (generated) >>>
-- DORPG P7：rpg_weapon_types (18) + rpg_weapons (390)
-- 產生自 scratchpad/dorpg_p7/weapons_all.json（已通過 validate_weapons.py）

ON CONFLICT (id) DO UPDATE SET
  job_id = EXCLUDED.job_id,
  name = EXCLUDED.name,
  visual = EXCLUDED.visual,
  elemental_capable = EXCLUDED.elemental_capable,
  description = EXCLUDED.description,
  traits = EXCLUDED.traits,
  sort_order = EXCLUDED.sort_order;

ON CONFLICT (id) DO UPDATE SET
  type_id = EXCLUDED.type_id,
  tier = EXCLUDED.tier,
  name = EXCLUDED.name,
  rarity = EXCLUDED.rarity,
  level_req = EXCLUDED.level_req,
  element = EXCLUDED.element,
  profile = EXCLUDED.profile,
  description = EXCLUDED.description,
  is_active = EXCLUDED.is_active,
  sort_order = EXCLUDED.sort_order;

-- <<< WEAPONS SEED <<<

-- ---------------------------------------------------------------------------
-- 3) player_equipment：目前只有 weapon 一個 slot（未來防具再加，CHECK 值域跟著擴充）。
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS player_equipment (
  user_id     UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  slot        TEXT NOT NULL CHECK (slot IN ('weapon')),
  item_id     TEXT NOT NULL REFERENCES rpg_weapons(id),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (user_id, slot)
);

